// shared/biomes/garden.js — Garden biome map, built from a black/white wall mask PNG.
//
// Source: hand-designed black/white PNG (black = wall/collision, white =
// open/walkable). Before building the mask, the small hollow ring marking
// the player spawn point was detected and erased (it's a location pin, not
// intended collision geometry — left in place it would wall the player into
// a tiny box at spawn). The mask below is the corrected image, thresholded
// and downsampled 2x (conservative — a block only counts as open if every
// source pixel in it was open, so no passage gets thinned or sealed by the
// downsample), then packed to 1 bit/tile and base64-encoded.
//
// UPDATE: further corrected multiple times using the in-game wall-tagging
// debug tool (tools/mapDebug.js):
//  - Tiles wrongly blocking movement along the walkable-area boundary were
//    flipped from wall to open (three batches).
//  - A small pocket of open tiles fully sealed off from the rest of the map
//    (unreachable — a ring-shaped wall enclosing a gap) was converted to wall.
//  - 18 isolated decorative rock/wall specks sitting in open floor (each
//    disconnected from the main cave wall) were erased to open floor.
//
// Grid: 663 x 592 tiles, each tile = 300 world units.
// World size: 198900 x 177600.
//
// This module intentionally mirrors the exported function shape of the old
// game/world.js (canMoveTo, findSafeSpawnPosition, drawMap, MAP_W/MAP_H) so it can
// be dropped in as a drag-in replacement once verified in-game.

export const GRID_W = 663;
export const GRID_H = 592;
export const TILE_SIZE = 300;


export const MAP_W = GRID_W * TILE_SIZE;
export const MAP_H = GRID_H * TILE_SIZE;


// Player spawn, in world units (converted from the PNG's marked spawn tile).
// Note: this constant is now only used as a fallback (see
// findSafeSpawnPosition below) — the real spawn behavior picks a random
// point inside the spawn chamber's safe zone every time.
const SPAWN_WORLD_X = 7650.0;
const SPAWN_WORLD_Y = 6750.0;

// ── Spawn chamber ──────────────────────────────────────────────────────────
// The room the spawn marker sits in is much larger than the marker itself
// and not centered on it (the marker was placed near a corner of the room
// in the source art, not its middle). SPAWN_CHAMBER_CENTER is the room's
// true geometric center — found by isolating the chamber from the rest of
// the connected map (the room reads as a single wide blob in the original
// artwork before narrowing into corridors; isolated here via morphological
// erosion at a radius comfortably larger than the corridor width but
// smaller than the room's own narrowest span, which breaks the corridors
// while leaving the room intact as its own connected piece, then dilated
// back to recover the room's real boundary) and averaging every tile
// inside it.
//
// SPAWN_SAFE_ZONE is the subset of the chamber that stays at least 5 tiles
// (1500 world units) from the chamber's own edge everywhere — so a random
// point drawn from it can never land close to a wall, even near the zone's
// own boundary. Encoded the same way as the main wall mask (1 bit/tile,
// packed, base64) but cropped to just its own small bounding box, since
// it only covers a fraction of the map.
export const SPAWN_CHAMBER_CENTER_TILE = { gx: 57, gy: 45 };
export const SPAWN_CHAMBER_CENTER = {
  x: (SPAWN_CHAMBER_CENTER_TILE.gx + 0.5) * TILE_SIZE,
  y: (SPAWN_CHAMBER_CENTER_TILE.gy + 0.5) * TILE_SIZE,
};

const SAFE_ZONE_GX0 = 21, SAFE_ZONE_GY0 = 20, SAFE_ZONE_W = 76, SAFE_ZONE_H = 52;
const SAFE_ZONE_B64 =
  '';

function _base64ToBytesEager(b64) {
  const binStr = atob(b64);
  const bytes = new Uint8Array(binStr.length);
  for (let i = 0; i < binStr.length; i++) bytes[i] = binStr.charCodeAt(i);
  return bytes;
}
const SAFE_ZONE_BYTES_PER_ROW = Math.ceil(SAFE_ZONE_W / 8);
const _safeZonePacked = _base64ToBytesEager(SAFE_ZONE_B64);

function isInSpawnSafeZone(gx, gy) {
  const lx = gx - SAFE_ZONE_GX0, ly = gy - SAFE_ZONE_GY0;
  if (lx < 0 || lx >= SAFE_ZONE_W || ly < 0 || ly >= SAFE_ZONE_H) return false;
  const byteIndex = ly * SAFE_ZONE_BYTES_PER_ROW + (lx >> 3);
  const bitIndex = 7 - (lx & 7);
  return ((_safeZonePacked[byteIndex] >> bitIndex) & 1) === 1;
}

// All safe-zone tile coordinates, flattened once at module load, so picking
// a uniformly random one at spawn time is an O(1) array index instead of a
// rejection-sample loop.
const _safeZoneTiles = [];
for (let ly = 0; ly < SAFE_ZONE_H; ly++) {
  for (let lx = 0; lx < SAFE_ZONE_W; lx++) {
    const byteIndex = ly * SAFE_ZONE_BYTES_PER_ROW + (lx >> 3);
    const bitIndex = 7 - (lx & 7);
    if ((_safeZonePacked[byteIndex] >> bitIndex) & 1) {
      _safeZoneTiles.push({ gx: SAFE_ZONE_GX0 + lx, gy: SAFE_ZONE_GY0 + ly });
    }
  }
}

