function worldToTile(x, y) {
  return { gx: Math.floor(x / TILE_SIZE), gy: Math.floor(y / TILE_SIZE) };
}

export function canMoveTo(x, y, radius = 22) {
  if (x - radius < 0 || x + radius > MAP_W ||
      y - radius < 0 || y + radius > MAP_H) return false;

  const points = [
    [x, y],
    [x - radius, y], [x + radius, y],
    [x, y - radius], [x, y + radius],
  ];
  for (const [px, py] of points) {
    const { gx, gy } = worldToTile(px, py);
    if (!isOpenTile(gx, gy)) return false;
  }
  return true;
}

// Picks a uniformly random tile from the spawn chamber's safe zone (every
// tile in it is guaranteed >=5 tiles/1500 units from any wall, verified at
// build time — see SPAWN_CHAMBER_CENTER above), then adds a small random
// offset within that tile so repeated spawns don't all land on exact tile-
// center grid points. Falls back to the old fixed marker position only if
// the safe zone is ever empty (should never happen; kept as a last resort
// so spawning can't hard-fail).
export function findSafeSpawnPosition(radius = 22, playerX, playerY, safeRadius = 350) {
  if (_safeZoneTiles.length > 0) {
    for (let attempt = 0; attempt < 20; attempt++) {
      const tile = _safeZoneTiles[Math.floor(Math.random() * _safeZoneTiles.length)];
      // Small in-tile jitter, kept well clear of the tile's own edges so the
      // player's radius can never poke past the safe-zone tile boundary.
      const jitterRange = TILE_SIZE * 0.5;
      const wx = (tile.gx + 0.5) * TILE_SIZE + (Math.random() - 0.5) * jitterRange;
      const wy = (tile.gy + 0.5) * TILE_SIZE + (Math.random() - 0.5) * jitterRange;
      if (!canMoveTo(wx, wy, radius)) continue;
      if (playerX !== undefined && Math.hypot(wx - playerX, wy - playerY) < safeRadius) continue;
      return { x: wx, y: wy };
    }
    // 20 random attempts failing is extremely unlikely given the zone's
    // size, but fall through to the old fixed-point search below rather
    // than give up.
  }

  if (canMoveTo(SPAWN_WORLD_X, SPAWN_WORLD_Y, radius)) {
    if (playerX === undefined || Math.hypot(SPAWN_WORLD_X - playerX, SPAWN_WORLD_Y - playerY) >= safeRadius) {
      return { x: SPAWN_WORLD_X, y: SPAWN_WORLD_Y };
    }
  }
  const { gx: sgx, gy: sgy } = worldToTile(SPAWN_WORLD_X, SPAWN_WORLD_Y);
  for (let r = 1; r < 40; r++) {
    for (let dx = -r; dx <= r; dx++) {
      for (let dy = -r; dy <= r; dy++) {
        if (Math.max(Math.abs(dx), Math.abs(dy)) !== r) continue;
        const gx = sgx + dx, gy = sgy + dy;
        if (!isOpenTile(gx, gy)) continue;
        const wx = (gx + 0.5) * TILE_SIZE, wy = (gy + 0.5) * TILE_SIZE;
        if (canMoveTo(wx, wy, radius)) return { x: wx, y: wy };
      }
    }
  }
  return { x: SPAWN_WORLD_X, y: SPAWN_WORLD_Y };
}

// Finds a randomized open spot near (nearX, nearY) that's kept clear of
// walls by `clearanceTiles` in every direction — used to respawn a player at
// a checkpoint the same way findSafeSpawnPosition spawns them at the map's
// own spawn chamber (a random nearby spot, never jammed right up against a
// wall), rather than always the exact same fixed point. Unlike the spawn
// chamber's pre-baked safe zone (checked once at build time), this checks
// clearance live since checkpoints can be anywhere on the map — cheap enough
// since it only runs once per respawn, not every frame.
export function findSafeSpawnNear(nearX, nearY, radius = 22, clearanceTiles = 3) {
  const { gx: cgx, gy: cgy } = worldToTile(nearX, nearY);

  function hasClearance(gx, gy, clearance) {
    for (let dy = -clearance; dy <= clearance; dy++) {
      for (let dx = -clearance; dx <= clearance; dx++) {
        if (!isOpenTile(gx + dx, gy + dy)) return false;
      }
    }
    return true;
  }

  // Search outward in rings, trying progressively further tiles, at the
  // requested clearance first.
  for (const clearance of [clearanceTiles, 2, 1, 0]) {
    const candidates = [];
    for (let r = 0; r <= 12; r++) {
      for (let dx = -r; dx <= r; dx++) {
        for (let dy = -r; dy <= r; dy++) {
          if (Math.max(Math.abs(dx), Math.abs(dy)) !== r) continue;
          const gx = cgx + dx, gy = cgy + dy;
          if (!isOpenTile(gx, gy)) continue;
          if (!hasClearance(gx, gy, clearance)) continue;
          candidates.push({ gx, gy });
        }
      }
      // Stop growing the search once we have a reasonable pool to pick from
      // at this clearance level — no need to scan the whole map.
      if (candidates.length >= 8) break;
    }
    if (candidates.length > 0) {
      const tile = candidates[Math.floor(Math.random() * candidates.length)];
      const jitterRange = TILE_SIZE * 0.5;
      const wx = (tile.gx + 0.5) * TILE_SIZE + (Math.random() - 0.5) * jitterRange;
      const wy = (tile.gy + 0.5) * TILE_SIZE + (Math.random() - 0.5) * jitterRange;
      if (canMoveTo(wx, wy, radius)) return { x: wx, y: wy };
      // Jitter pushed us into a wall corner — fall back to exact tile center.
      return { x: (tile.gx + 0.5) * TILE_SIZE, y: (tile.gy + 0.5) * TILE_SIZE };
    }
  }

  // Total fallback — shouldn't happen for any checkpoint placed in an open
  // tunnel, but never hard-fail a respawn.
  return { x: nearX, y: nearY };
}

export function findOpenSpawnPosition(radius, existingMobs, tries = 60) {
  for (let i = 0; i < tries; i++) {
    const gx = Math.floor(Math.random() * GRID_W);
    const gy = Math.floor(Math.random() * GRID_H);
    const x = (gx + 0.5) * TILE_SIZE, y = (gy + 0.5) * TILE_SIZE;
    if (!canMoveTo(x, y, radius)) continue;
    let clear = true;
    if (existingMobs) {
      for (const m of existingMobs) {
        if (m.dead) continue;
        if (Math.hypot(x - m.x, y - m.y) < radius + m.radius + 12) { clear = false; break; }
      }
    }
    if (clear) return { x, y };
  }
  return null;
}
